style.css:
@-moz-document domain("pinterest.com") {
/* Force all backgrounds to void black */
  html, body, * {
    background-color: #000000 !important;
    color: #eeeeee !important;
    border-color: #330000 !important;
    box-shadow: none !important;
  }

  /* Remove white backgrounds */
  [style*="background-color: white"],
  [style*="background-color:#fff"],
  [style*="background: white"],
  [style*="background:#fff"],
  [style*="#fff"],
  [style*="white"] {
    background-color: #000000 !important;
    color: #eeeeee !important;
  }

  /* Header and nav */
  header,
  [data-test-id="header"],
  nav,
  [data-test-id="left-nav-bar"],
  [role="search"],
  [role="banner"],
  [data-test-id="app-header"] {
    background-color: #000000 !important;
    border-bottom: 1px solid #330000 !important;
  }

  /* Boards & Pins */
  [data-test-id*="pin"],
  [data-test-id*="board"],
  .Board-Item,
  .Collection-Item,
  .gridCentered,
  .hCL,
  .Hql {
    background-color: #000000 !important;
    border: 1px solid #440000 !important;
    box-shadow: 0 0 6px rgba(139, 0, 0, 0.2) !important;
  }

  /* Force text to light */
  span, div, p, h1, h2, h3, h4, h5, h6, a, button, input {
    color: #eeeeee !important;
  }

  /* Remove shadow overlays */
  .boxShadow, .shadow, .css-1pgo0u6, .css-1v0mbdj {
    box-shadow: none !important;
  }

  /* Buttons */
  button,
  .button,
  .Button {
    background-color: #110000 !important;
    color: #eeeeee !important;
    border: 1px solid #330000 !important;
    border-radius: 6px !important;
  }

  button:hover,
  .button:hover {
    background-color: #220000 !important;
    color: #ff4d4d !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #000000 !important;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #660000 !important;
    border-radius: 10px;
  }

  /* Tabs & filter bar */
  [data-test-id="search-guides-bar"],
  [data-test-id="search-suggestions-bar"],
  [role="tablist"] {
    background-color: #000000 !important;
    border-bottom: 1px solid #330000 !important;
  }

  /* Ads or promo content (optional hide) */
  [data-test-id="ad"], 
  [data-test-id="pinPromotedLabel"],
  [data-test-id="promoted-label"] {
    display: none !important;
  }

  /* SVGs */
  svg, svg path {
    fill: #eeeeee !important;
  }

  svg:hover, svg path:hover {
    fill: #ff1a1a !important;
  }

  /* Ensure cards and popups are black */
  [class*="Card"], 
  [class*="Modal"], 
  [class*="overlay"], 
  [class*="popover"], 
  [class*="Dropdown"] {
    background-color: #000000 !important;
    color: #eeeeee !important;
  }
}
